const msg = $input.first().json.message || {};
const text = msg.text || '';
const chatId = msg.chat ? msg.chat.id : null;
const match = text.match(/0x[a-fA-F0-9]{40}/);
return [{
  json: {
    chatId,
    contract: match ? match[0] : '',
    hasAddress: match ? 'yes' : 'no'
  }
}];

const items = $input.all().map((i) => i.json);
const arr = Array.isArray(items[0]) ? items[0] : items;
const byId = {};
for (const r of arr) {
  if (r && typeof r.id !== 'undefined') byId[r.id] = r.result;
}
const code = byId[1];
const chatId = $('Extract contract address').first().json.chatId;
const contract = $('Extract contract address').first().json.contract;

function decodeString(hex) {
  if (!hex || hex === '0x') return null;
  const h = hex.slice(2);
  if (h.length < 128) return null;
  const len = parseInt(h.slice(64, 128), 16);
  if (!isFinite(len) || len < 0 || len > 200) return null;
  let out = '';
  for (let i = 0; i < len; i++) {
    out += String.fromCharCode(parseInt(h.slice(128 + i * 2, 130 + i * 2), 16));
  }
  return out.replace(/\0/g, '').trim() || null;
}

function decodeUint(hex) {
  if (!hex || hex === '0x') return null;
  try { return BigInt(hex).toString(); } catch { return null; }
}

const name = decodeString(byId[2]);
const symbol = decodeString(byId[3]);
const supply = decodeUint(byId[4]);

let reply;
if (!code || code === '0x') {
  reply = '⛔ DO NOT MINT\n\n' + contract + '\n\nNo contract code at this address on BSC. Nothing to mint — any site asking you to mint here is a scam.';
} else {
  reply = '⚠️ NEEDS MANUAL CHECK\n\n' + contract + '\n'
    + 'Name: ' + (name || 'unknown') + '\n'
    + 'Symbol: ' + (symbol || 'unknown') + '\n'
    + 'Total supply: ' + (supply || 'unknown') + '\n\n'
    + 'This is a real contract, but this check does NOT verify the mint price or whether the mint is open.\n'
    + 'Before minting: confirm the price is 0, preview the transaction (value 0, gas only), and never approve unlimited spending.';
}

return [{ json: { chatId, contract, reply } }];
